def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]

    # Each highlighted patch is a solid, rectangular monochrome region.
    # Detect whole 4-connected components so adjacent same-colored cells
    # outside the patch cannot be accidentally included.
    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen[r][c] = True
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1,x), (y+1,x), (y,x-1), (y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        stack.append((ny, nx))
            ys = [y for y, x in cells]
            xs = [x for y, x in cells]
            r0, r1 = min(ys), max(ys)
            c0, c1 = min(xs), max(xs)
            if len(cells) >= 25 and len(cells) == (r1-r0+1)*(c1-c0+1):
                for y, x in cells:
                    out[y][x] = 4
    return out
